import { describe, expect, it } from "vitest";
import fx from "./allocation-transitions.fixture.json";
import {
  ALLOCATION_STATUSES,
  allocationTransitionAllowed,
} from "./allocation-transitions";

// Same fixture as the pgTAP test (generated by scripts/gen-allocation-transitions-test.mjs): SQL and TS cannot drift.
describe("allocationTransitionAllowed: all 64 pairs from the shared fixture", () => {
  it("lists the same eight statuses", () => {
    expect([...ALLOCATION_STATUSES]).toEqual(fx.statuses);
  });
  const allowed = fx.allowed as Record<string, string[]>;
  for (const from of fx.statuses)
    for (const to of fx.statuses) {
      const want = allowed[from].includes(to);
      it(`${from} -> ${to}: ${want ? "allowed" : "refused"}`, () => {
        expect(allocationTransitionAllowed(from, to)).toBe(want);
      });
    }
  it("null, unknown and wrongly-cased values allow nothing", () => {
    expect(allocationTransitionAllowed(null, "planned")).toBe(false);
    expect(allocationTransitionAllowed("planned", undefined)).toBe(false);
    expect(allocationTransitionAllowed("bogus", "planned")).toBe(false);
    expect(allocationTransitionAllowed("Planned", "cancelled")).toBe(false);
  });
});
